// 操作数栈
stack<Fractions> operaorNum;
// 操作符栈
stack<char> operatorSign;
// 记录除0的非常操作
bool invalidFlag = false;
​
void calc() {
    Fractions b = operaorNum.top();
    operaorNum.pop();
​
    Fractions a = operaorNum.top();
    operaorNum.pop();
​
    char op = operatorSign.top();
    operatorSign.pop();
    Fractions result;
    // 四则运算
    switch (op) {
        case '+':
            result.fa = a.fa  * b.fa;
            result.ch = a.ch * b.fa + b.ch * a.fa;
            break;
        case '-':
            result.fa = a.fa  * b.fa;
            result.ch = a.ch * b.fa - b.ch * a.fa;
            break;
        case '*':
            result.fa = a.fa  * b.fa;
            result.ch = a.ch *  b.ch ;
            break;
        case '/':
            result.fa = a.fa  * b.ch;
            result.ch = a.ch * b.fa;
