            ) {
                calc();
            }
            operatorStack.push(c);
        } else if (c === ")") {
            while (operatorStack.length && operatorStack[operatorStack.length - 1] !== "(") {
                calc();
            }
            operatorStack.pop(); // 移除左括号
        } else if (c === "(") {
            operatorStack.push(c);
        }
