import (
    "bufio"
    "fmt"
    "os"
    "strconv"
    "strings"
)
​
// 分数结构体
type Fraction struct {
    fa int // 分母
    ch int // 分子
}
​
// 操作数栈
var operatorNum []Fraction
// 操作符栈
var operatorSign []rune
// 记录除0的非法操作
var invalidFlag bool = false
​
// 计算四则运算
func calc() {
    b := operatorNum[len(operatorNum)-1]
    operatorNum = operatorNum[:len(operatorNum)-1]
​
    a := operatorNum[len(operatorNum)-1]
    operatorNum = operatorNum[:len(operatorNum)-1]
​
    op := operatorSign[len(operatorSign)-1]
    operatorSign = operatorSign[:len(operatorSign)-1]
​
    var result Fraction
    switch op {
    case '+':
        result = Fraction{a.fa * b.fa, a.ch*b.fa + b.ch*a.fa}
    case '-':
        result = Fraction{a.fa * b.fa, a.ch*b.fa - b.ch*a.fa}
    case '*':
        result = Fraction{a.fa * b.fa, a.ch * b.ch}
    case '/':
        if b.ch == 0 {
            invalidFlag = true
            return
        }
        result = Fraction{a.fa * b.ch, a.ch * b.fa}
    }
​
    if result.fa == 0 {
        invalidFlag = true
    }
    operatorNum = append(operatorNum, result)
}
​
// 求最大公约数
func gcd(a, b int) int {
    for b != 0 {
        a, b = b, a%b
    }
    if a < 0 {
        return -a
    }
    return a
}
​
// 解析并计算表达式
func solve(express string) string {
    operatorPriority := map[rune]int{'+': 1, '-': 1, '*': 2, '/': 2}
​
    numStr := ""
    for pos := 0; pos < len(express); pos++ {
        if invalidFlag {
            break
        }
        c := rune(express[pos])
​
        if c >= '0' && c <= '9' {
            numStr += string(c)
            if pos+1 >= len(express) || express[pos+1] < '0' || express[pos+1] > '9' {
                val, _ := strconv.Atoi(numStr)
                operatorNum = append(operatorNum, Fraction{1, val})
                numStr = ""
            }
        } else if c == '+' || c == '-' || c == '*' || c == '/' {
            for len(operatorSign) > 0 && operatorSign[len(operatorSign)-1] != '(' &&
                operatorPriority[c] <= operatorPriority[operatorSign[len(operatorSign)-1]] {
                calc()
            }
            operatorSign = append(operatorSign, c)
        } else if c == ')' {
            for operatorSign[len(operatorSign)-1] != '(' {
                calc()
            }
            operatorSign = operatorSign[:len(operatorSign)-1] // 移除 '('
        } else if c == '(' {
            operatorSign = append(operatorSign, c)
        }
    }
​
    for len(operatorNum) > 1 {
        calc()
    }
​
    result := operatorNum[0]
    if result.fa == 0 || invalidFlag {
        return "ERROR"
    }
​
    k := gcd(result.fa, result.ch)
    result.fa /= k
    result.ch /= k
​
    sign := ""
    if result.fa*result.ch < 0 {
        sign = "-"
    }
​
    fa, ch := abs(result.fa), abs(result.ch)
    if fa == 1 {
        return fmt.Sprintf("%s%d", sign, ch)
    } else {
        return fmt.Sprintf("%s%d/%d", sign, ch, fa)
    }
}
​
// 绝对值
func abs(x int) int {
    if x < 0 {
        return -x
    }
    return x
}
​
func main() {
    reader := bufio.NewReader(os.Stdin)
    express, _ := reader.ReadString('\n')
    express = strings.TrimSpace(express)
​
    fmt.Println(solve(express))
}
